"""Report overlaps in a DXF produced by build_dxf.py, using the AutoCAD-calibrated text model.

Checks: text vs text, text vs cable lines (layer LINES), text vs symbols (layers CLOSURES / ENDPOINTS).
"""
import ezdxf

from .metrics import mtext_height, text_width

EPS = 0.05
BOXH = 1.3          # TEXT box height / text height (caps + descender)


def hit(a, b):
    return a[0] < b[2] - EPS and b[0] < a[2] - EPS and a[1] < b[3] - EPS and b[1] < a[3] - EPS


def text_rect(e):
    h = e.dxf.height
    w = text_width(e.dxf.text, h)
    bh = BOXH * h
    align, p, _ = e.get_placement()
    name = align.name
    x0 = p.x if "LEFT" in name else (p.x - w if "RIGHT" in name else p.x - w / 2)
    if name.startswith("TOP"):
        y0 = p.y - bh
    elif name.startswith("MIDDLE"):
        y0 = p.y - bh / 2
    else:
        y0 = p.y
    return (x0, y0, x0 + w, y0 + bh)


def mtext_rect(e):
    assert e.dxf.attachment_point == 2, "only top-centre MTEXT is expected"
    w = e.dxf.width
    top = e.dxf.insert.y
    hgt = mtext_height(e.text, e.dxf.char_height, w) + 1.0
    return (e.dxf.insert.x - w / 2, top - hgt, e.dxf.insert.x + w / 2, top)


def line_hits_text(l, t):
    return l[0] < t[2] - EPS and l[2] > t[0] + EPS and l[1] < t[3] - EPS and l[3] > t[1] + EPS



def check_dxf(path):
    """Returns (number_of_problems, report_text)."""
    msp = ezdxf.readfile(path).modelspace()
    texts, lines, symbols = [], [], []
    for e in msp:
        t, layer = e.dxftype(), e.dxf.layer
        if t == "TEXT" and e.dxf.text.strip():
            assert abs(e.dxf.get("rotation", 0)) < 1, "rotated text found"
            texts.append((text_rect(e), e.dxf.text[:38]))
        elif t == "MTEXT":
            assert abs(e.dxf.get("rotation", 0)) < 1, "rotated text found"
            texts.append((mtext_rect(e), e.text.replace("\n", " ")[:38]))
        elif t == "LINE" and layer == "LINES":
            s, en = e.dxf.start, e.dxf.end
            lines.append((min(s.x, en.x), min(s.y, en.y), max(s.x, en.x), max(s.y, en.y)))
        elif t == "LWPOLYLINE" and layer == "LINES":
            pts = [(p[0], p[1]) for p in e.get_points()]
            for (x1, y1), (x2, y2) in zip(pts, pts[1:]):
                lines.append((min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)))
        elif t == "CIRCLE" and layer == "ENDPOINTS":
            c, r = e.dxf.center, e.dxf.radius
            symbols.append((c.x - r, c.y - r, c.x + r, c.y + r))
        elif t == "LWPOLYLINE" and layer in ("CLOSURES", "ENDPOINTS"):
            xs = [p[0] for p in e.get_points()]
            ys = [p[1] for p in e.get_points()]
            symbols.append((min(xs), min(ys), max(xs), max(ys)))


    tt = [(a[1], b[1]) for i, a in enumerate(texts) for b in texts[i + 1:] if hit(a[0], b[0])]
    tl = [(t[1], l) for t in texts for l in lines if line_hits_text(l, t[0])]
    ts = [(t[1], s) for t in texts for s in symbols if hit(t[0], s)]

    xs = [v for r, _ in texts for v in (r[0], r[2])] + [v for l in lines for v in (l[0], l[2])]
    ys = [v for r, _ in texts for v in (r[1], r[3])] + [v for l in lines for v in (l[1], l[3])]
    out = [f"{len(texts)} text entities | drawing extents {max(xs) - min(xs):.0f} x {max(ys) - min(ys):.0f}"]
    out.append(f"  text vs text overlaps    : {len(tt)}")
    out.append(f"  text vs cable line hits  : {len(tl)}")
    out.append(f"  text vs symbol overlaps  : {len(ts)}")
    for a, b in tt[:8]:
        out.append(f"    T/T : {a!r} <-> {repr(b)}")
    for a, l in tl[:8]:
        out.append(f"    T/L : {a!r} <-> line {tuple(round(float(v), 1) for v in l)}")
    for a, s in ts[:8]:
        out.append(f"    T/S : {a!r} <-> symbol {tuple(round(float(v), 1) for v in s)}")
    return len(tt) + len(tl) + len(ts), "\n".join(out)

cmld/core.py:
"""Data loading and validation shared by every output.

A *row* is [device, street, lat, lon, cable_out, note]. `note` is "" when empty.
CABLE IN is never stored: it is always the CABLE OUT of the previous row.
"""
import json
import os
import re

CABLE_RE = re.compile(r'CABLE\s+(.*?),?\s*TUBE:\s*(.*?)\s*CORE\s*:\s*(.*)', re.IGNORECASE)
COLOURS = {"BLUE", "ORANGE", "GREEN", "BROWN", "SLATE", "WHITE", "RED", "BLACK", "YELLOW", "VIOLET", "ROSE", "AQUA"}


class DataError(Exception):
    pass


def strip_seq(device):
    """'3).3M 288' -> '3M 288' (the Excel output writes devices as 'N).Name')."""
    return re.sub(r'^\s*\d+\s*\)\s*\.?\s*', '', str(device)).strip()


def to_float(v, what, rownum):
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v or "").strip().replace(" ", "")
    if s.count(",") == 1 and "." not in s:          # '-6,229934' (Indonesian decimal comma)
        s = s.replace(",", ".")
    try:
        return float(s)
    except ValueError:
        raise DataError(f"Baris {rownum}: {what} '{v}' bukan angka")


# --- loaders ------------------------------------------------------------------------------------
def load_json(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    rows = []
    for i, r in enumerate(data, start=1):
        if len(r) < 5:
            raise DataError(f"Baris {i}: butuh minimal 5 elemen [device, street, lat, lon, cable_out]")
        rows.append([str(r[0]).strip(), str(r[1]).strip(), to_float(r[2], "latitude", i),
                     to_float(r[3], "longitude", i), str(r[4]).strip(),
                     str(r[5]).strip() if len(r) > 5 and r[5] else ""])
    return rows, []


HEADER_ALIASES = {
    "device": ["DEVICE", "PERANGKAT", "NAMA"],
    "cable_in": ["CABLE IN", "CABLE_IN"],
    "cable_out": ["CABLE OUT", "CABLE_OUT"],
    "street": ["STREET", "JALAN", "ALAMAT"],
    "lat": ["LATITUDE", "LAT"],
    "lon": ["LONGITUDE", "LON", "LONG", "LNG"],
    "note": ["CATATAN", "NOTE", "KETERANGAN"],
}


def load_xlsx(path):
    """Read a Data Mancore workbook (Sheet1 or the first sheet). Columns are found by header name."""
    from openpyxl import load_workbook
    wb = load_workbook(path, data_only=False)
    ws = wb["Sheet1"] if "Sheet1" in wb.sheetnames else wb.worksheets[0]

    header_row, cols = None, {}
    for r in range(1, min(ws.max_row, 10) + 1):
        found = {}
        for c in range(1, ws.max_column + 1):
            v = str(ws.cell(r, c).value or "").strip().upper()
            for key, names in HEADER_ALIASES.items():
                if v in names and key not in found:
                    found[key] = c
        if {"device", "cable_out", "lat", "lon"} <= found.keys():
            header_row, cols = r, found
            break
    if header_row is None:
        raise DataError("Header tidak ketemu. Perlu kolom DEVICE, CABLE OUT, LATITUDE, LONGITUDE (STREET, CATATAN opsional).")

    rows, cable_in_given = [], []
    for r in range(header_row + 1, ws.max_row + 1):
        get = lambda k: ws.cell(r, cols[k]).value if k in cols else None
        device = get("device")
        if device is None or str(device).strip() == "":
            continue
        rows.append([strip_seq(device), str(get("street") or "").strip(),
                     to_float(get("lat"), "LATITUDE", r), to_float(get("lon"), "LONGITUDE", r),
                     str(get("cable_out") or "-").strip(), str(get("note") or "").strip()])
        cable_in_given.append((r, get("cable_in")))
    return rows, cable_in_given


def load_kmz(path):
    """CMLD KMZ (as written by this program, possibly edited in Google Earth) -> rows, extras.

    extras = {"paths": {i: [(lat, lon), ...]}  cable route from device i to i+1 as drawn in Google Earth,
              "poles": [(label, lat, lon), ...]}
    """
    import re as _re
    import zipfile
    import xml.etree.ElementTree as ET
    if path.lower().endswith(".kmz"):
        with zipfile.ZipFile(path) as z:
            name = next((n for n in z.namelist() if n.lower().endswith(".kml")), None)
            if name is None:
                raise DataError("KMZ tidak berisi file .kml")
            xml = z.read(name)
    else:
        with open(path, "rb") as f:
            xml = f.read()
    root = ET.fromstring(xml)
    q = lambda tag: "{http://www.opengis.net/kml/2.2}" + tag

    def coords_of(pm, geom):
        g = pm.find(".//" + q(geom))
        if g is None:
            return None
        c = g.find(".//" + q("coordinates"))
        pts = []
        for tok in (c.text or "").split():
            parts = tok.split(",")
            if len(parts) >= 2:
                pts.append((float(parts[1]), float(parts[0])))
        return pts

    devices, paths, poles, warnings = {}, {}, [], []
    for pm in root.iter(q("Placemark")):
        data = {sd.get("name"): (sd.text or "").strip() for sd in pm.iter(q("SimpleData"))}
        name = (pm.findtext(q("name")) or "").strip()
        line = coords_of(pm, "LineString")
        point = coords_of(pm, "Point")
        dev = data.get("DEVICE") or name
        if line and " To " in dev:
            m = _re.match(r"\s*(\d+)\s*\)", dev)
            if m:
                paths[int(m.group(1)) - 1] = line
            continue
        if point and "DEVICE" in data:
            m = _re.match(r"\s*(\d+)\s*\)", data["DEVICE"])
            if not m:
                warnings.append(f"Titik '{data['DEVICE']}' tanpa nomor urut 'N).' - dilewati")
                continue
            lat, lon = point[0]
            devices[int(m.group(1))] = [strip_seq(data["DEVICE"]), data.get("STREET", ""), lat, lon,
                                        data.get("CABLE_OUT", "-") or "-", ""]
            continue
        if point:
            pole_id = next((v for k, v in data.items() if "pole_id" in k.lower() and v), "")
            if pole_id or "pole" in name.lower() or name.upper().startswith(("LN ", "TN ", "TIANG")):
                poles.append((pole_id or name, point[0][0], point[0][1]))
    doc_el = root.find(q("Document"))
    doc_name = ((doc_el.findtext(q("name")) if doc_el is not None else "") or "").strip()
    if not devices:
        rows, extras, warn = _load_kmz_plain(root, q, coords_of)
        extras["name"] = doc_name
        return rows, extras, warn
    order = sorted(devices)
    if order != list(range(1, len(order) + 1)):
        warnings.append(f"Nomor urut perangkat di KMZ tidak berurutan: {order}")
    rows = [devices[k] for k in order]
    return rows, {"paths": paths, "poles": poles, "name": doc_name}, warnings


FIRST_FOLDERS = ("OLT", "AGG", "HUB", "HB", "ODC")
LAST_FOLDERS = ("FDT", "HUB BOX", "FAT", "END", "ODP")
MID_FOLDERS = ("CLOSURE", "JC", "JOINT", "SPLICE")
POLE_FOLDERS = ("POLE", "TIANG")
CABLE_FOLDERS = ("CABLE", "KABEL", "ROUTE", "JALUR")


def _load_kmz_plain(root, q, coords_of):
    """Field KMZ with folders like OLT / CLOSURE / FDT / CABLE / POLE and plain placemark names
    (no CMLD data). Device order follows the cable names 'A TO B', starting at the OLT."""
    import math as _m
    import re as _re
    devices, lines, poles, warnings = [], [], [], []

    def role_of(folder):
        f = folder.upper().strip()
        for role, keys in (("pole", POLE_FOLDERS), ("cable", CABLE_FOLDERS), ("first", FIRST_FOLDERS),
                           ("last", LAST_FOLDERS), ("mid", MID_FOLDERS)):
            if any(f == k or f.startswith(k + " ") or f.startswith(k + "_") for k in keys):
                return role
        return None

    def walk(el, role):
        for ch in el:
            tag = ch.tag.split("}")[-1]
            if tag == "Folder":
                walk(ch, role_of(ch.findtext(q("name")) or "") or role)
            elif tag == "Document":
                walk(ch, role)
            elif tag == "Placemark":
                name = (ch.findtext(q("name")) or "").strip()
                line, point = coords_of(ch, "LineString"), coords_of(ch, "Point")
                if line and len(line) >= 2:
                    lines.append((name, line))
                elif point:
                    if role == "pole":
                        poles.append((name, point[0][0], point[0][1]))
                    else:
                        devices.append({"name": name, "lat": point[0][0], "lon": point[0][1], "role": role})
    walk(root, None)
    if not devices:
        raise DataError("Tidak ada titik perangkat di KMZ (folder OLT / CLOSURE / FDT tidak ketemu).")

    by_name = {d["name"].upper(): d for d in devices}
    nxt, paths_by_pair = {}, {}
    for name, pts in lines:
        m = _re.match(r"^\s*(?:\d+\)\.?\s*)?(.+?)\s+TO\s+(?:\d+\)\.?\s*)?(.+?)\s*$", name, _re.I)
        if m and m.group(1).upper() in by_name and m.group(2).upper() in by_name:
            a, b = m.group(1).upper(), m.group(2).upper()
            nxt[a] = b
            paths_by_pair[(a, b)] = pts
        else:
            # names do not match (e.g. 'WAK15C2401 TO DKG39800 (FDT ID NY)'): match the line ends to the
            # nearest devices instead (within ~25 m)
            def near(p):
                d = min(devices, key=lambda e: _m.hypot(e["lat"] - p[0], (e["lon"] - p[1]) * 0.994))
                return d if _m.hypot(d["lat"] - p[0], d["lon"] - p[1]) * 111000 < 25 else None
            da, db = near(pts[0]), near(pts[-1])
            if m and m.group(1).upper() in by_name:
                da = by_name[m.group(1).upper()]
            if da and db and da is not db:
                a, b = da["name"].upper(), db["name"].upper()
                if m and m.group(1).upper() == b:
                    a, b, pts = b, a, pts[::-1]
                nxt[a] = b
                paths_by_pair[(a, b)] = pts
            else:
                warnings.append(f"Garis kabel '{name}' tidak bisa dicocokkan ke dua perangkat (format 'A TO B')")

    firsts = [d for d in devices if d["role"] == "first"] or devices[:1]
    lasts = [d for d in devices if d["role"] == "last"]
    order = [firsts[0]]
    used = {id(firsts[0])}
    while True:
        cur = order[-1]["name"].upper()
        if cur in nxt and id(by_name[nxt[cur]]) not in used:
            d = by_name[nxt[cur]]
        else:
            # next = a device that starts a cable chain and is not used yet, nearest first; FDT kept for last
            rest = [d for d in devices if id(d) not in used and d not in lasts]
            if not rest:
                break
            starts = [d for d in rest if d["name"].upper() in nxt] or rest
            c = order[-1]
            d = min(starts, key=lambda e: _m.hypot(e["lat"] - c["lat"], e["lon"] - c["lon"]))
        order.append(d)
        used.add(id(d))
    for d in lasts:
        if id(d) not in used:
            order.append(d)
            used.add(id(d))
    rows = [[d["name"], "", d["lat"], d["lon"], "", ""] for d in order]
    rows[-1][4] = "-"
    paths = {}
    for i in range(len(order) - 1):
        key = (order[i]["name"].upper(), order[i + 1]["name"].upper())
        if key in paths_by_pair:
            paths[i] = paths_by_pair[key]
    warnings.append("KMZ ini tanpa data CMLD: CABLE OUT dan STREET kosong - lengkapi di Excel hasil sebelum dikirim")
    return rows, {"paths": paths, "poles": poles, "plain": True}, warnings


def load_rows(path):
    """Returns (rows, warnings). Raises DataError on unusable data."""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".json":
        rows, cin = load_json(path)
    elif ext in (".xlsx", ".xlsm"):
        rows, cin = load_xlsx(path)
    elif ext in (".kmz", ".kml"):
        rows, _extras, kw = load_kmz(path)
        if len(rows) < 2:
            raise DataError("Minimal 2 perangkat")
        return rows, kw + validate(rows)
    else:
        raise DataError("Input harus .xlsx, .kmz, atau .json")
    if len(rows) < 2:
        raise DataError("Minimal 2 perangkat")
    warnings = validate(rows)
    # literal CABLE IN values in Excel (not the =C{row} formula) must match the previous CABLE OUT
    for k, (r, val) in enumerate(cin):
        if k == 0 or val is None or str(val).startswith("="):
            continue
        if norm(val) != norm(rows[k - 1][4]):
            warnings.append(f"Baris Excel {r}: CABLE IN '{val}' beda dengan CABLE OUT baris atasnya "
                            f"'{rows[k - 1][4]}' (yang dipakai: CABLE OUT baris atas)")
    return rows, warnings


def save_json(rows, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump([r[:5] + ([r[5]] if r[5] else []) for r in rows], f, ensure_ascii=False, indent=2)


# --- validation ---------------------------------------------------------------------------------
def norm(s):
    return re.sub(r"\s+", " ", str(s)).strip().upper()


def split_cable(text):
    """'CABLE 24C/4T, TUBE: BLUE, CORE : BLUE, ORANGE' -> ('24C/4T', 'BLUE', 'BLUE, ORANGE') or (None,)*3."""
    m = CABLE_RE.match(text)
    if not m:
        return None, None, None
    return m.group(1).strip(), m.group(2).strip().rstrip(',').strip(), m.group(3).strip()


def validate(rows):
    w = []
    n = len(rows)
    for i, (device, street, lat, lon, out, note) in enumerate(rows, start=1):
        if not -90 <= lat <= 90 or not -180 <= lon <= 180:
            hint = " - sepertinya LATITUDE/LONGITUDE tertukar" if abs(lon) <= 90 else ""
            w.append(f"#{i} {device}: koordinat di luar jangkauan ({lat}, {lon}){hint}")
        if i > 1 and abs(lat - rows[i - 2][2]) + abs(lon - rows[i - 2][3]) > 0.5:
            w.append(f"#{i} {device}: jauh sekali (>50 km) dari perangkat sebelumnya - cek koordinat")
        if not street:
            w.append(f"#{i} {device}: STREET kosong")
        if i < n:
            ctype, tube, core = split_cable(out)
            if ctype is None:
                w.append(f"#{i} {device}: CABLE OUT tidak terbaca (pola 'CABLE <tipe>, TUBE: <tube>, CORE : <core>'): '{out}'")
            else:
                for c in re.findall(r"[A-Z]+", re.sub(r"LAYER", "", core.upper())):
                    if c not in COLOURS:
                        w.append(f"#{i} {device}: warna core '{c}' tidak dikenal")
        elif out not in ("-", ""):
            w.append(f"#{i} {device}: perangkat terakhir seharusnya CABLE OUT '-', isinya '{out}'")
    return w

cmld/hb.py:
"""Diagram HB: one hub (HB) feeding N ports; every port serves one line with two FATs (01 = SB, 02 = EB).

Excel input (first sheet): column B = LINE, column C = FAT CODE, column I = PANJANG (cable length, m).
A blank LINE cell continues the line above (the second FAT of the line).
"""
import math
import os
import re

import ezdxf
from ezdxf.enums import TextEntityAlignment

from .core import DataError

CODE_RE = re.compile(r"^[A-Z0-9]+S\d{2}[A-Z]\d{2}$", re.I)


def hub_name_of(code):
    """'FXXXXXS01A01' -> 'FXXXXX' (the FAT code minus its S..A.. suffix)."""
    m = re.match(r"^(.*?)S\d{2}[A-Z]\d{2}$", code, re.I)
    return m.group(1) if m else code


def parse_len(v):
    if v is None or str(v).strip() == "":
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().lower().replace(",", ".").rstrip("m").strip()
    try:
        return float(s)
    except ValueError:
        return None


SINGLE_AS = "sb"       # a line with only one device: that device is a SUB BOX (code ..01)
MAX_LINES = 8          # 8 lines = 4 splitters (S01..S04), two lines per splitter


def splitter_of(line, index):
    """Line A/B -> 1, C/D -> 2, ... (from the letter; falls back to the position)."""
    if len(line) == 1 and "A" <= line <= "Z":
        return (ord(line) - 65) // 2 + 1
    return index // 2 + 1


def make_code(hub, line, index, end):
    return f"{hub}S{splitter_of(line, index):02d}{line}{'01' if end == 'sb' else '02'}"


def _norm(v):
    return re.sub(r"\s+", " ", str(v or "")).strip().upper()


def load_hb_xlsx(path):
    """Three layouts, recognised from the headers:
    1. simple   : HB <name> on top, then LINE | PANJANG SB | PANJANG EB  (FAT codes generated)
    2. per line : LINE | SB | PANJANG SB | EB | PANJANG EB
    3. old      : column B = LINE, C = FAT CODE, I = PANJANG, one FAT per row
    """
    from openpyxl import load_workbook
    ws = load_workbook(path, data_only=True).worksheets[0]
    hub, hdr_row, cols = None, None, {}
    for r in range(1, min(ws.max_row, 15) + 1):
        vals = {c: _norm(ws.cell(r, c).value) for c in range(1, min(ws.max_column, 30) + 1)}
        for c, v in vals.items():
            if v in ("HB", "NAMA HB", "HUB") and c + 1 <= ws.max_column and _norm(ws.cell(r, c + 1).value):
                hub = str(ws.cell(r, c + 1).value).strip()
        found = {}
        for c, v in vals.items():
            if v == "LINE": found["line"] = c
            elif v in ("PANJANG SB", "SB PANJANG", "PANJANG 01"): found["len_sb"] = c
            elif v in ("PANJANG EB", "EB PANJANG", "PANJANG 02"): found["len_eb"] = c
            elif v in ("SB", "FAT SB", "KODE SB"): found["sb"] = c
            elif v in ("EB", "FAT EB", "KODE EB"): found["eb"] = c
        if {"line", "len_sb", "len_eb"} <= found.keys():
            hdr_row, cols = r, found
            break
    if hdr_row is None:
        return load_hb_old(ws)

    items, warnings = [], []
    for r in range(hdr_row + 1, ws.max_row + 1):
        line = _norm(ws.cell(r, cols["line"]).value)
        if not line:
            continue
        idx = len({it["line"] for it in items})
        blank = lambda v: v is None or str(v).strip() in ("", "-")
        given = {e: (str(ws.cell(r, cols[e]).value or "").strip() if e in cols else "",
                     ws.cell(r, cols["len_" + e]).value) for e in ("sb", "eb")}
        filled = [e for e in ("sb", "eb") if given[e][0] or not blank(given[e][1])]
        if len(filled) == 1:
            # one device on this line: it is SINGLE_AS, whichever column was filled
            src = filled[0]
            code = given[src][0] or (make_code(hub, line, idx, SINGLE_AS) if hub else "")
            if not code:
                raise DataError("Nama HB tidak ada. Isi sel 'HB' lalu nama HB di sebelahnya (mis. HB | FXXXXX).")
            length = parse_len(given[src][1])
            if length is None:
                warnings.append(f"Baris {r}: PANJANG line {line} kosong / bukan angka")
            items.append({"row": r, "line": line, "code": code, "len": length, "first": True, "end": SINGLE_AS})
            continue
        if not filled:
            warnings.append(f"Baris {r}: line {line} tidak punya perangkat (PANJANG SB dan EB kosong)")
            continue
        for end in ("sb", "eb"):
            code = given[end][0]
            if not code:
                if hub is None:
                    raise DataError("Nama HB tidak ada. Isi sel 'HB' lalu nama HB di sebelahnya (mis. HB | FXXXXX).")
                code = make_code(hub, line, idx, end)
            length = parse_len(ws.cell(r, cols["len_" + end]).value)
            if length is None:
                warnings.append(f"Baris {r}: PANJANG {end.upper()} line {line} kosong / bukan angka")
            items.append({"row": r, "line": line, "code": code, "len": length, "first": end == "sb", "end": end})
    return items, warnings


def load_hb_old(ws):
    items, warnings, cur_line = [], [], None
    for r in range(1, ws.max_row + 1):
        code = str(ws.cell(r, 3).value or "").strip()
        if not code or code.upper() in ("FAT CODE", "FAT", "KODE FAT"):
            continue
        if not re.search(r"\d{2}$", code):
            continue
        line = str(ws.cell(r, 2).value or "").strip()
        if line.upper() == "LINE":
            continue
        if line:
            cur_line = line.upper()
        if cur_line is None:
            warnings.append(f"Baris {r}: kolom LINE kosong di baris pertama data")
            cur_line = "?"
        length = parse_len(ws.cell(r, 9).value)
        if length is None:
            warnings.append(f"Baris {r}: PANJANG (kolom I) kosong / bukan angka untuk {code}")
        items.append({"row": r, "line": cur_line, "code": code, "len": length, "first": bool(line)})
    return items, warnings


def load_hb_json(path):
    import json
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    items, cur = [], None
    for k, d in enumerate(data, start=1):
        line, code, length = (list(d) + [None, None, None])[:3]
        if line:
            cur = str(line).upper()
        items.append({"row": k, "line": cur or "?", "code": str(code), "len": parse_len(length), "first": bool(line)})
    return items, []


def group_lines(items, warnings):
    """-> hub name, [{line, sb, eb}] in order of appearance."""
    order, lines = [], {}
    for it in items:
        if it["line"] not in lines:
            order.append(it["line"])
            lines[it["line"]] = {"line": it["line"], "sb": None, "eb": None}
        L = lines[it["line"]]
        suffix = it["code"][-2:]
        slot = it.get("end") or ("sb" if suffix == "01" else "eb" if suffix == "02" else None)
        if slot is None:
            warnings.append(f"Baris {it['row']}: {it['code']} tidak berakhiran 01 (SB) atau 02 (EB)")
            slot = "sb" if L["sb"] is None else "eb"
        if L[slot] is not None:
            warnings.append(f"Line {it['line']}: {slot.upper()} ganda ({L[slot]['code']} dan {it['code']})")
        L[slot] = it
        if not CODE_RE.match(it["code"]):
            warnings.append(f"Baris {it['row']}: format FAT CODE tidak biasa: {it['code']}")
    out = [lines[k] for k in order]
    if len(out) > MAX_LINES:
        warnings.append(f"{len(out)} line - maksimal {MAX_LINES} line (4 splitter S01-S04)")
    for i, L in enumerate(out):
        want = splitter_of(L["line"], i)
        for slot in ("sb", "eb"):
            fat = L[slot]
            m = fat and re.search(r"S(\d{2})([A-Z])\d{2}$", fat["code"], re.I)
            if m and (int(m.group(1)) != want or m.group(2).upper() != L["line"]):
                warnings.append(f"Line {L['line']}: {fat['code']} seharusnya S{want:02d}{L['line']} (2 line per splitter)")
    for L in out:
        if L["sb"] is None and L["eb"] is None:
            warnings.append(f"Line {L['line']}: tidak ada perangkat")
    hubs = {hub_name_of(it["code"]) for it in items}
    hub = sorted(hubs)[0] if hubs else "HB"
    if len(hubs) > 1:
        warnings.append("FAT CODE berasal dari lebih dari satu HB: " + ", ".join(sorted(hubs)))
    return hub, out


def load_hb(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in (".xlsx", ".xlsm"):
        items, warnings = load_hb_xlsx(path)
    elif ext == ".json":
        items, warnings = load_hb_json(path)
    else:
        raise DataError("Input harus .xlsx")
    if not items:
        raise DataError("Tidak ada FAT CODE terbaca. Data dibaca dari kolom B (LINE), C (FAT CODE), I (PANJANG).")
    hub, lines = group_lines(items, warnings)
    return hub, lines, items, warnings


# --- drawing ---------------------------------------------------------------------------------------
# Symbols follow the CQT library: HUB BOX = triangle, SUB BOX (SB) / END BOX (EB) = octagons, "CQT" under each.
# Cables stop at the edge of every symbol, so no line ever crosses an icon or its text.
ROW = 34.0          # vertical distance between ports
HUB_S = 52.0        # hub triangle side
OCT_R = 9.0         # octagon circumradius (SUB BOX / END BOX)
BUS = 17.0          # first vertical bus offset from where the trunk leaves the hub
BUS_STEP = 2.6      # extra offset per port away from the middle
LABEL_X = 62.0      # port label start, measured from the trunk start
SB_X = 142.0
EB_X = 230.0
H_PORT, H_CODE, H_LEN, H_HUBNAME = 3.0, 2.4, 2.4, 2.4
H_HUB, H_HUB_CQT = 4.0, 5.0
H_BOX, H_BOX_CQT = 1.5, 1.6
PORTS_PER_BOX = 8
SB_RATIO = "30/70"

OCT_A = OCT_R * math.cos(math.radians(22.5))      # apothem: distance from centre to a flat side
HUB_H = HUB_S * math.sqrt(3) / 2


def octagon(cx, cy, r=OCT_R):
    """Flat top / bottom / left / right, like the CQT SUB BOX and END BOX symbols."""
    pts = [(cx + r * math.cos(math.radians(22.5 + 45 * k)), cy + r * math.sin(math.radians(22.5 + 45 * k))) for k in range(8)]
    return pts + [pts[0]]


def hub_triangle():
    """Equilateral, apex up, centroid at (0, 0)."""
    top, base = 2 * HUB_H / 3, -HUB_H / 3
    pts = [(0, top), (-HUB_S / 2, base), (HUB_S / 2, base)]
    return pts + [pts[0]]


def fmt_len(v):
    if v is None:
        return "-"
    return f"{int(v)}m" if float(v).is_integer() else f"{v:g}m"


def build_hb_dxf(hub, lines, out_path):
    doc = ezdxf.new(dxfversion="R2010")
    doc.units = ezdxf.units.M
    for name, color in (("HB", 1), ("FAT", 1), ("KABEL", 5), ("LABEL_PORT", 7), ("LABEL_FAT", 7)):
        doc.layers.add(name=name, color=color)
    msp = doc.modelspace()

    def text(s, x, y, h, layer, align=TextEntityAlignment.MIDDLE_CENTER):
        msp.add_text(s, dxfattribs={"layer": layer, "height": h}).set_placement((x, y), align=align)

    def cable(pts):
        msp.add_lwpolyline(pts, dxfattribs={"layer": "KABEL"})

    # HUB BOX
    base = -HUB_H / 3
    msp.add_lwpolyline(hub_triangle(), dxfattribs={"layer": "HB"})
    text("HUB BOX", 0, base + 10.5, H_HUB, "HB")
    text(f"{PORTS_PER_BOX} PORT", 0, base + 4.5, H_HUB, "HB")
    text("CQT", 0, base - 5.5, H_HUB_CQT, "HB")
    text(hub, 0, base - 11.5, H_HUBNAME, "LABEL_FAT")
    right = HUB_S / 3                                   # the triangle's right edge at y = 0

    def box(slot, x, y):
        msp.add_lwpolyline(octagon(x, y), dxfattribs={"layer": "FAT"})
        if slot == "sb":
            text("SUB BOX", x, y + 3.4, H_BOX, "FAT")
            text(f"{PORTS_PER_BOX} PORT", x, y + 1.3, H_BOX, "FAT")
            msp.add_line((x - 5.0, y - 0.2), (x + 5.0, y - 0.2), dxfattribs={"layer": "FAT"})
            text(SB_RATIO, x, y - 2.5, H_BOX, "FAT")
        else:
            text("END BOX", x, y + 1.3, H_BOX, "FAT")
            text(f"{PORTS_PER_BOX} PORT", x, y - 1.2, H_BOX, "FAT")
        text("CQT", x, y - OCT_A - 1.9, H_BOX_CQT, "FAT")

    n = len(lines)
    mid = (n - 1) / 2
    for i, L in enumerate(lines):
        y = (mid - i) * ROW
        # outer ports turn closest to the hub, inner ports further out: no cable crosses another
        xb = right + BUS + (mid - abs(i - mid)) * BUS_STEP * 2 + (BUS_STEP if i > mid else 0)
        sb_x, eb_x = right + SB_X, right + EB_X
        first_x = sb_x if L["sb"] else eb_x
        cable([(right, 0), (xb, 0), (xb, y), (first_x - OCT_A, y)])       # stops at the first box's flat side
        if L["sb"] and L["eb"]:
            cable([(sb_x + OCT_A, y), (eb_x - OCT_A, y)])                   # SB -> EB, edge to edge
        text(f"PORT {i + 1} FOR LINE {L['line']}", right + LABEL_X, y + 4.5, H_PORT, "LABEL_PORT",
             TextEntityAlignment.MIDDLE_LEFT)
        for slot, x in (("sb", sb_x), ("eb", eb_x)):
            fat = L[slot]
            if fat is None:
                continue
            box(slot, x, y)
            text(fat["code"], x, y + OCT_A + 3.2, H_CODE, "LABEL_FAT")
            text(fmt_len(fat["len"]), x, y - OCT_A - 6.2, H_LEN, "LABEL_FAT")
    doc.saveas(out_path)
    return f"DXF HB: {hub}, {n} port, {sum(1 for L in lines for s in ('sb', 'eb') if L[s])} FAT"


def build_hb_template(out_path, hub="FXXXXX"):
    """Simple input: HB name once, then LINE | PANJANG SB | PANJANG EB (codes are generated)."""
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
    wb = Workbook()
    ws = wb.active
    ws.title = "HB"
    thin = Side(style="thin", color="B7C6D9")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    head = dict(font=Font(bold=True, color="FFFFFF"), fill=PatternFill("solid", fgColor="1F3864"))
    ws["A1"], ws["B1"] = "HB", hub
    ws["A1"].font, ws["A1"].fill = head["font"], head["fill"]
    ws["B1"].font = Font(bold=True)
    for c, h in enumerate(["LINE", "PANJANG SB", "PANJANG EB"], start=1):
        cell = ws.cell(3, c, h)
        cell.font, cell.fill, cell.border = head["font"], head["fill"], border
        cell.alignment = Alignment(horizontal="center")
    for k, (sb, eb) in enumerate([(62, 46), (32, 88), (33, 68), (195, 54), (106, 61), (203, 203)]):
        for c, v in enumerate([chr(65 + k), sb, eb], start=1):
            cell = ws.cell(4 + k, c, v)
            cell.border, cell.alignment = border, Alignment(horizontal="center")
    ws["E3"] = "Catatan"
    ws["E3"].font = Font(bold=True)
    notes = ["Isi nama HB di sel B1.", "Satu baris = satu line (maks 8: A-H).",
             "Kode FAT dibuat otomatis: line A/B = S01, C/D = S02, E/F = S03, G/H = S04.",
             "Panjang dalam meter (angka saja).", "Line yang hanya punya 1 perangkat: isi satu PANJANG saja, perangkatnya SUB BOX (kode ..01).", "Kalau kode FAT di lapangan beda, tambah kolom SB dan EB berisi kodenya."]
    for k, t in enumerate(notes):
        ws.cell(4 + k, 5, t).font = Font(italic=True, color="666666")
    for col, w in {"A": 8, "B": 14, "C": 14, "D": 3, "E": 70}.items():
        ws.column_dimensions[col].width = w
    wb.save(out_path)

cmld/metrics.py:
"""Text metrics calibrated against how the user's AutoCAD actually draws the CMLD DXF text.

Measured on a screenshot (text height -> width): '(ORANGE (LAYER 2))' h4.0 -> 67 units, 'YELLOW, ROSE' h3.6 -> 47,
'288C/24T' h4.8 -> 37, '-6.216104, 106.822167' h3.4 -> 59, '12). NWC 144 (One Pole)' h4.8 -> 98, 'Jl.Karet Belakang Raya' h4.0 -> 80.
That is about 40% wider than a typical proportional-font estimate (uppercase ~1.2 x height), so layout must use this model.
The model below is within +7..+13 % of every measured sample (always on the safe side).
"""

UPPER, LOWER, DIGIT, SPACE = 1.20, 0.95, 0.95, 0.65
PUNCT = {"(": 0.55, ")": 0.55, ",": 0.45, ".": 0.45, "/": 0.75, "-": 0.65, ":": 0.50, ";": 0.50, "&": 1.10, "#": 1.00}
SAFETY = 1.08
LINE_PITCH = 5 / 3          # MTEXT line pitch (x text height) at line-spacing factor 1.0


def char_w(c):
    if c.isupper():
        return UPPER
    if c.islower():
        return LOWER
    if c.isdigit():
        return DIGIT
    if c == " ":
        return SPACE
    return PUNCT.get(c, 0.80)


def text_width(s, h):
    return sum(char_w(c) for c in s) * h * SAFETY


def wrap_lines(text, h, width):
    """Greedy word wrap at spaces, like MTEXT. A single unbreakable word is never split."""
    lines, cur = [], ""
    for word in text.split(" "):
        trial = word if not cur else cur + " " + word
        if not cur or text_width(trial, h) <= width:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    lines.append(cur)
    return lines


def mtext_height(text, h, width):
    """Total height of a wrapped MTEXT block (first line = h, every further line adds one pitch)."""
    return h + (len(wrap_lines(text, h, width)) - 1) * h * LINE_PITCH

cmld/icons.py:
"""Link Net legend icons (blocks from LEGEND ICON LINK NET.dxf) for the geographic DXF.

assets/legend_linknet.dxf holds the icon blocks plus the whole legend table as block LEGEND_LINKNET
(top-left corner at 0,0). Block names are kept exactly as in the original legend.
"""
import os
import re

import ezdxf
from ezdxf.addons import Importer

ASSET = os.path.join(os.path.dirname(__file__), "assets", "legend_linknet.dxf")
LEGEND = "LEGEND_LINKNET"

# unscaled icon width (drawing units of the legend) - used to scale icons to the map text height
SIZE = {"NEW OLT": 13.42, "EXSISTING OLT": 13.42, "FDT 96C": 7.47, "FDT 48C": 7.47,
        "EXSISTING FDT 96C": 27.11, "EXSISTING FDT 48C": 27.11, "COIL": 3.65}
for _c in ("48C", "96C", "144C"):
    SIZE[f"NEW CLOSURE {_c}"] = SIZE[f"EXSISTING CLOSURE {_c}"] = 10.98
SIZE["EXSISTING CLOSURE MPO"] = 10.98
for _p in ("LN 7250", "LN 8200", "NP 7250", "NP 8200"):
    SIZE[_p] = 4.3
for _p in ("MTI", "FMI", "PLN", "MR"):
    SIZE[_p] = 3.5

# cable colour per fibre type (ACI), same as the legend lines
CABLE_COLOR = {(6, 1): 30, (12, 2): 1, (24, 3): 3, (24, 4): 5, (36, 6): 34, (48, 4): 230, (48, 6): 4,
               (72, 6): 204, (96, 8): 62, (144, 12): 120}
CORE_ONLY = {6: 30, 12: 1, 24: 3, 36: 34, 48: 4, 72: 204, 96: 62, 144: 120}


def install(doc):
    """Copy the icon blocks + legend block into doc (once)."""
    if LEGEND in doc.blocks:
        return
    src = ezdxf.readfile(ASSET)
    imp = Importer(src, doc)
    imp.import_blocks([b.name for b in src.blocks if not b.name.startswith("*")])
    imp.finalize()


def cable_spec(spec):
    """'CABLE 24C/4T, TUBE: ...' -> (24, 4); 'CABLE MPO' -> ('MPO', None); unknown -> (None, None)."""
    s = (spec or "").upper()
    if "MPO" in s:
        return "MPO", None
    m = re.search(r"(\d+)\s*C\s*/\s*(\d+)\s*T", s)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.search(r"(\d+)\s*C\b", s)
    return (int(m.group(1)), None) if m else (None, None)


def cable_color(spec):
    core, tube = cable_spec(spec)
    if not isinstance(core, int):
        return None
    return CABLE_COLOR.get((core, tube)) or CORE_ONLY.get(core)


def _cap(core, sizes):
    if core == "MPO":
        return "MPO"
    if not isinstance(core, int):
        return sizes[0]
    for s in sizes:
        if core <= int(s[:-1]):
            return s
    return sizes[-1]


NEW_CODE = re.compile(r"C\d{4}\b|D\d{2}\b", re.I)    # codes made by the project (…C2401, …D01) = new devices


def device_block(name, i, n, spec_in, spec_out, code=None):
    """Icon for device i of n. First = OLT/ODC/source (existing), FDT (last device, or any name with FDT),
    others = closure. NEW = coded by this project (…C2401, …D01, or the project FDT code from the KMZ name),
    everything else (3M 288, NWC 96, GARBART, other FDTs …) EXSISTING."""
    if i == 0:
        return "EXSISTING OLT"
    nm = (name or "").upper()
    core = cable_spec(spec_in)[0]
    new = bool(NEW_CODE.search(nm)) or bool(code and code.upper() in nm)
    if i == n - 1 or "FDT" in nm:
        cap = _cap(core, ["48C", "96C"])
        cap = "48C" if cap == "MPO" else cap
        return f"FDT {cap}" if new else f"EXSISTING FDT {cap}"
    core_out = cable_spec(spec_out)[0]
    big = max([c for c in (core, core_out) if isinstance(c, int)], default=None)
    cap = _cap("MPO" if "MPO" in (core, core_out) and big is None else big, ["48C", "96C", "144C"])
    if cap == "MPO":
        return "EXSISTING CLOSURE MPO"                  # the legend only has an existing MPO closure block
    return f"{'NEW' if new else 'EXSISTING'} CLOSURE {cap}"


def pole_block(pid):
    """LN / NP (7/250 default, 8/200 when the id says so), MTI, FMI, PLN, MR/MYREP; anything else = LN 7/250."""
    s = (pid or "").upper().replace(" ", "")
    for key, blk in (("MYREP", "MR"), ("MTI", "MTI"), ("FMI", "FMI"), ("PLN", "PLN")):
        if key in s:
            return blk
    if s.startswith("MR"):
        return "MR"
    kind = "NP" if s.startswith("NP") else "LN"
    tall = "8200" if re.search(r"8/?200|8M|9M", s) else "7250"
    return f"{kind} {tall}"

cmld/outline.py:
"""Road outlines (kerb lines) without shapely, so it runs in any Pyodide build.

Each road is a centreline with a width. The outline of all roads together is made of the parts of every road's
own kerb lines (both sides + round ends) that are not inside any road band. Kerbs are sampled every `step`
metres; a sample is kept when its distance to every centreline is >= that road's half width (minus a hair).
Kept samples are joined back into polylines and simplified.
"""
import math

STEP = 0.8          # sampling step along the kerbs (m)


def _seg_dist(px, py, ax, ay, bx, by):
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 == 0 else max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / L2))
    qx, qy = ax + dx * t - px, ay + dy * t - py
    return math.sqrt(qx * qx + qy * qy)


def _offset(pts, d):
    """Polyline offset by d to the left (miter joins, limited)."""
    out = []
    n = len(pts)
    for i in range(n):
        if i == 0:
            (x0, y0), (x1, y1) = pts[0], pts[1]
            L = math.hypot(x1 - x0, y1 - y0) or 1.0
            out.append((x0 - (y1 - y0) / L * d, y0 + (x1 - x0) / L * d))
        elif i == n - 1:
            (x0, y0), (x1, y1) = pts[-2], pts[-1]
            L = math.hypot(x1 - x0, y1 - y0) or 1.0
            out.append((x1 - (y1 - y0) / L * d, y1 + (x1 - x0) / L * d))
        else:
            (xa, ya), (xb, yb), (xc, yc) = pts[i - 1], pts[i], pts[i + 1]
            L1 = math.hypot(xb - xa, yb - ya) or 1.0
            L2 = math.hypot(xc - xb, yc - yb) or 1.0
            n1 = (-(yb - ya) / L1, (xb - xa) / L1)
            n2 = (-(yc - yb) / L2, (xc - xb) / L2)
            mx, my = n1[0] + n2[0], n1[1] + n2[1]
            ml = math.hypot(mx, my)
            if ml < 1e-6:
                out.append((xb + n1[0] * d, yb + n1[1] * d))
                continue
            mx, my = mx / ml, my / ml
            cos_half = mx * n1[0] + my * n1[1]
            k = d / max(cos_half, 0.35)                 # miter limit
            if cos_half < 0.7:                          # sharp bend: add both normals (bevel-ish)
                out.append((xb + n1[0] * d, yb + n1[1] * d))
                out.append((xb + mx * k, yb + my * k))
                out.append((xb + n2[0] * d, yb + n2[1] * d))
            else:
                out.append((xb + mx * k, yb + my * k))
    return out


def _sample(pl, step):
    out = [pl[0]]
    for (x0, y0), (x1, y1) in zip(pl, pl[1:]):
        L = math.hypot(x1 - x0, y1 - y0)
        k = max(1, int(L / step))
        for j in range(1, k + 1):
            t = j / k
            out.append((x0 + (x1 - x0) * t, y0 + (y1 - y0) * t))
    return out


def _cap(c, prev, d, step):
    """Half circle around end point c, away from prev."""
    ang = math.atan2(c[1] - prev[1], c[0] - prev[0])
    k = max(4, int(math.pi * d / step))
    return [(c[0] + d * math.cos(ang + math.pi / 2 - math.pi * j / k),
             c[1] + d * math.sin(ang + math.pi / 2 - math.pi * j / k)) for j in range(k + 1)]


def _simplify(pts, tol):
    """Douglas-Peucker."""
    if len(pts) < 3:
        return pts
    keep = [False] * len(pts)
    keep[0] = keep[-1] = True
    stack = [(0, len(pts) - 1)]
    while stack:
        a, b = stack.pop()
        ax, ay = pts[a]
        bx, by = pts[b]
        best, idx = -1.0, -1
        for i in range(a + 1, b):
            d = _seg_dist(pts[i][0], pts[i][1], ax, ay, bx, by)
            if d > best:
                best, idx = d, i
        if best > tol:
            keep[idx] = True
            stack += [(a, idx), (idx, b)]
    return [p for p, k in zip(pts, keep) if k]


def road_outlines(roads, box, step=STEP, simplify=0.25):
    """roads: [(pts, width)]; box: (xmin, ymin, xmax, ymax). Returns kerb polylines [[(x, y), ...]]."""
    CELL = 25.0
    grid = {}
    segs = []
    for ri, (pts, w) in enumerate(roads):
        for a, b in zip(pts, pts[1:]):
            si = len(segs)
            segs.append((a[0], a[1], b[0], b[1], w / 2))
            r = w / 2
            for gx in range(int(math.floor((min(a[0], b[0]) - r) / CELL)), int(math.floor((max(a[0], b[0]) + r) / CELL)) + 1):
                for gy in range(int(math.floor((min(a[1], b[1]) - r) / CELL)), int(math.floor((max(a[1], b[1]) + r) / CELL)) + 1):
                    grid.setdefault((gx, gy), []).append(si)
    x0, y0, x1, y1 = box

    def free(p):
        if not (x0 <= p[0] <= x1 and y0 <= p[1] <= y1):
            return False
        for si in grid.get((int(math.floor(p[0] / CELL)), int(math.floor(p[1] / CELL))), ()):
            ax, ay, bx, by, r = segs[si]
            if _seg_dist(p[0], p[1], ax, ay, bx, by) < r - 0.02:
                return False
        return True

    out = []
    for pts, w in roads:
        if len(pts) < 2:
            continue
        d = w / 2
        left = _offset(pts, d)
        right = _offset(pts, -d)
        ring = left + _cap(pts[-1], pts[-2], d, step)[1:-1] + right[::-1] + _cap(pts[0], pts[1], d, step)[1:-1]
        ring.append(ring[0])
        def edge(pf, pn):                           # boundary point between a free and a covered sample
            for _ in range(7):
                m = ((pf[0] + pn[0]) / 2, (pf[1] + pn[1]) / 2)
                if free(m):
                    pf = m
                else:
                    pn = m
            return pf

        run, prev, prev_free = [], None, False
        for p in _sample(ring, step):
            f = free(p)
            if f:
                if not prev_free and prev is not None:
                    run.append(edge(p, prev))
                run.append(p)
            elif prev_free:
                run.append(edge(prev, p))
                if len(run) > 1:
                    out.append(run)
                run = []
            prev, prev_free = p, f
        if len(run) > 1:
            out.append(run)
    # join runs that continue each other (the ring start/end split) and simplify
    res = []
    for r in out:
        s = _simplify(r, simplify)
        if len(s) >= 2 and sum(math.dist(a, b) for a, b in zip(s, s[1:])) > step * 1.5:
            res.append([(round(x, 3), round(y, 3)) for x, y in s])
    return res
